191	    /**
192	     * Known E.164 country codes whose national-number length is fixed, used to split the stored
193	     * telephone into its country code and national digits for display: Australia ({@code '61'}) and
194	     * the North American Numbering Plan ({@code '1'}). A number whose country code is not listed is
195	     * split by taking its leading digit as the (minimal) country code.
196	     */
197	    private static final Map<String, Integer> COUNTRY_NATIONAL_LENGTH = Map.of("61", 9, "1", 10);
198	
199	    /**
200	     * The stored E.164 {@link #getTelephone() telephone} formatted for humans: the country code, a
201	     * single space, then the national digits grouped in threes from the left (e.g. the stored
202	     * {@code '+61412345678'} becomes {@code '+61 412 345 678'}). The raw telephone itself stays in
203	     * E.164 form. Returns the stored value unchanged when it is absent or not a {@code '+'}-prefixed
204	     * digit string.
205	     *
206	     * @return the human-readable telephone, or the stored value when it cannot be formatted
207	     */
208	    public String getTelephoneDisplay() {
209	        if (this.telephone == null || !this.telephone.matches("\\+[0-9]+")) {
210	            return this.telephone;
211	        }
212	        String digits = this.telephone.substring(1);
213	        String countryCode = extractCountryCode(digits);
214	        String national = digits.substring(countryCode.length());
215	        StringBuilder display = new StringBuilder("+").append(countryCode);
216	        for (int i = 0; i < national.length(); i += 3) {
217	            display.append(' ').append(national, i, Math.min(i + 3, national.length()));
218	        }
219	        return display.toString();
220	    }
221	
222	    /**
223	     * Splits the country code off an E.164 digit string (country code followed by national digits,
224	     * without the leading {@code '+'}). A country code listed in {@link #COUNTRY_NATIONAL_LENGTH}
225	     * whose required national-number length matches the remaining digits is preferred; failing that,
226	     * the leading digit is used as the country code.
227	     *
228	     * @param digits the E.164 digits without the leading {@code '+'}
229	     * @return the country-code portion of {@code digits}
230	     */
231	    private static String extractCountryCode(String digits) {
232	        for (Map.Entry<String, Integer> entry : COUNTRY_NATIONAL_LENGTH.entrySet()) {
233	            String code = entry.getKey();
234	            if (digits.startsWith(code) && digits.length() - code.length() == entry.getValue()) {
235	                return code;
236	            }
237	        }
238	        return digits.substring(0, 1);
239	    }
