265	    /**
266	     * The owner's age band, derived from the {@link #getBirthDate() birth date} as at the owner's
267	     * {@link #getRegistrationDate() registration date}: {@code 'MINOR'} when under 18, {@code 'ADULT'}
268	     * when 18 to 64, and {@code 'SENIOR'} when 65 or older. The age is the number of whole years
269	     * elapsed from the birth date to the registration date (defaulting to the server's current date
270	     * when no registration date is set yet). Returns {@code null} when no birth date was supplied.
271	     *
272	     * @return the age band, or {@code null} when the birth date is absent
273	     */
274	    public String getAgeBand() {
275	        if (this.birthDate == null) {
276	            return null;
277	        }
278	        LocalDate asAt = this.registrationDate != null ? this.registrationDate : LocalDate.now();
279	        int years = Period.between(this.birthDate, asAt).getYears();
280	        if (years < 18) {
281	            return "MINOR";
282	        }
283	        if (years < 65) {
284	            return "ADULT";
285	        }
286	        return "SENIOR";
287	    }
