297	    /**
298	     * The owner's membership number, formatted {@code '<customerCode>-M<YY>'} where {@code YY} is
299	     * the last two digits of the registration date's year (e.g. {@code 'NSW-1A2B3C4D-M26'}). Derived
300	     * from the owner's own customer code and registration date; {@code null} when either is absent.
301	     *
302	     * @return the membership number, or {@code null} when it cannot be derived
303	     */
304	    public String getMembershipNumber() {
305	        if (this.customerCode == null || this.registrationDate == null) {
306	            return null;
307	        }
308	        return String.format("%s-M%02d", this.customerCode, this.registrationDate.getYear() % 100);
309	    }
310	
311	    /**
312	     * The owner's Luhn check digit, a single digit (0-9) computed over the digits contained in the
313	     * {@link #getCustomerCode() customer code}. Non-digit characters (such as the separators and the
314	     * letter prefixes) are ignored. Returns {@code null} when the customer code is absent.
315	     *
316	     * @return the Luhn check digit, or {@code null} when the customer code is absent
317	     */
318	    public Integer getCheckDigit() {
319	        if (this.customerCode == null) {
320	            return null;
321	        }
322	        int sum = 0;
323	        boolean dbl = true;
324	        for (int i = this.customerCode.length() - 1; i >= 0; i--) {
325	            char c = this.customerCode.charAt(i);
326	            if (c < '0' || c > '9') {
327	                continue;
328	            }
329	            int d = c - '0';
330	            if (dbl) {
331	                d *= 2;
332	                if (d > 9) {
333	                    d -= 9;
334	                }
335	            }
336	            sum += d;
337	            dbl = !dbl;
338	        }
339	        return (10 - (sum % 10)) % 10;
340	    }
341	
342	    /**
343	     * The owner's membership points, the score the {@link #getMembershipLevel() membership level} is
344	     * derived from. The score starts at 0 and gains: 2 when an email address is present, 1 when the
345	     * owner has no namesakes ({@code namesakeCount} is 0), 2 for a household of 3 or more members
346	     * ({@code householdSize} is at least 3), and 3 when the owner's tenure exceeds 365 days (see
347	     * {@link #getTenureDays()}). Because a newly created owner has zero tenure, the tenure points are
348	     * never awarded at create time.
349	     *
350	     * @return the membership points, a non-negative integer
351	     */
352	    public Integer getMembershipPoints() {
353	        int points = 0;
354	        boolean hasEmail = this.email != null && !this.email.isBlank();
355	        if (hasEmail) {
356	            points += 2;
357	        }
358	        boolean hasNoNamesakes = this.namesakeCount != null && this.namesakeCount == 0;
359	        if (hasNoNamesakes) {
360	            points += 1;
361	        }
362	        if (this.householdSize != null && this.householdSize >= 3) {
363	            points += 2;
364	        }
365	        Long tenureDays = getTenureDays();
366	        if (tenureDays != null && tenureDays > 365) {
367	            points += 3;
368	        }
369	        return points;
370	    }
371	
372	    /**
373	     * The owner's numeric membership level, mapped from the {@link #getMembershipPoints() membership
374	     * points}: level 1 for 0-1 points, level 2 for 2-3 points, level 3 for 4-5 points, and level 4
375	     * for 6 or more points.
376	     *
377	     * @return the membership level, an integer from 1 to 4
378	     */
379	    public Integer getMembershipLevel() {
380	        int points = getMembershipPoints();
381	        if (points <= 1) {
382	            return 1;
383	        }
384	        if (points <= 3) {
385	            return 2;
386	        }
387	        if (points <= 5) {
388	            return 3;
389	        }
390	        return 4;
391	    }
392	
393	    /**
394	     * The owner's tenure in whole days, the number of days elapsed from the
395	     * {@link #getRegistrationDate() registration date} to the server's current date. A tenure of more
396	     * than 365 days is what raises the {@link #getMembershipLevel() membership level} to 4. Returns
397	     * {@code null} when no registration date has been set yet.
398	     *
399	     * @return the tenure in whole days, or {@code null} when the registration date is absent
400	     */
401	    public Long getTenureDays() {
402	        if (this.registrationDate == null) {
403	            return null;
404	        }
405	        return ChronoUnit.DAYS.between(this.registrationDate, LocalDate.now());
406	    }
407	
408	    /**
409	     * The owner's locality, the canonical region string. Once the owner has a
410	     * {@link #getCustomerCode() customer code} the locality is the {@code <REGION>} component of that
411	     * code (the text before the first {@code '-'}), so the locality and the identity share a single
412	     * source of truth. Before the customer code is assigned (for example while a create is still
413	     * validating the postcode) it falls back to the region the code will be built from: the
414	     * {@link #getPostcode() postcode} looked up by range first (NSW 2000-2099, VIC 3000-3099,
415	     * QLD 4000-4099), then the fixed city-to-region table (Sydney->NSW, Melbourne->VIC,
416	     * Brisbane->QLD), and finally {@code 'UNKNOWN'} when neither resolves to a region.
417	     *
418	     * @return the canonical region string, or {@code 'UNKNOWN'}
419	     */
420	    public String getLocality() {
421	        if (this.customerCode != null) {
422	            int dash = this.customerCode.indexOf('-');
423	            return dash >= 0 ? this.customerCode.substring(0, dash) : this.customerCode;
424	        }
425	        return deriveRegion();
426	    }
427	
428	    /**
429	     * The owner's IANA timezone name, derived from the owner's {@link #getLocality() locality} via the
430	     * fixed region-to-timezone table: NSW->Australia/Sydney, VIC->Australia/Melbourne,
431	     * QLD->Australia/Brisbane. Returns {@code null} when the locality is not one of these regions (for
432	     * example the {@code 'UNKNOWN'} locality of a city with no known region).
433	     *
434	     * @return the IANA timezone name, or {@code null} when the locality has no mapped timezone
435	     */
436	    public String getTimezone() {
437	        return REGION_TIMEZONE.get(getLocality());
438	    }
439	
440	    /**
441	     * The region the customer code's {@code <REGION>} component is built from: the postcode looked up
442	     * by range first (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099), falling back to the fixed
443	     * city-to-region table (Sydney->NSW, Melbourne->VIC, Brisbane->QLD) when the postcode is absent or
444	     * in no known range, and {@code 'UNKNOWN'} when neither resolves. Preferring the postcode returns
445	     * the same region for known cities but disambiguates cities that share a name.
446	     *
447	     * @return the canonical region string, or {@code 'UNKNOWN'}
448	     */
449	    private String deriveRegion() {
450	        String region = regionFromPostcode();
451	        if (region != null) {
452	            return region;
453	        }
454	        return CITY_REGION.getOrDefault(this.city, "UNKNOWN");
455	    }
456	
457	    /**
458	     * Builds this owner's customer code, formatted {@code '<REGION>-<HASH8>'}. {@code REGION} is the
459	     * region derived from the postcode (falling back to the city, then {@code 'UNKNOWN'}; see
460	     * {@link #deriveRegion()}) and {@code HASH8} is the first 8 upper-case hexadecimal characters of
461	     * the SHA-256 digest of the owner's normalized telephone concatenated with its last name (e.g.
462	     * {@code 'NSW-1A2B3C4D'}). The code carries no sequence number, so it is a pure function of the
463	     * owner's region, telephone and last name. Call this once at create time and store the result via
464	     * {@link #setCustomerCode(String)}, which thereafter backs {@link #getLocality()},
465	     * {@link #getMembershipNumber()} and {@link #getCheckDigit()}.
466	     *
467	     * @return the assembled customer code
468	     */
469	    public String buildCustomerCode() {
470	        return deriveRegion() + "-" + sha256Hex8(this.telephone + this.getLastName());
471	    }
472	
473	    /**
474	     * Computes the first 8 upper-case hexadecimal characters (the first 4 bytes) of the SHA-256 digest
475	     * of the given value's UTF-8 bytes, the {@code HASH8} component of the customer code.
476	     *
477	     * @param value the value to hash
478	     * @return the 8-character upper-case hex prefix of the SHA-256 digest
479	     */
480	    private static String sha256Hex8(String value) {
481	        try {
482	            byte[] digest = MessageDigest.getInstance("SHA-256")
483	                .digest(value.getBytes(StandardCharsets.UTF_8));
484	            StringBuilder hex = new StringBuilder(8);
485	            for (int i = 0; i < 4; i++) {
486	                hex.append(String.format("%02X", digest[i]));
487	            }
488	            return hex.toString();
489	        }
490	        catch (NoSuchAlgorithmException e) {
491	            throw new IllegalStateException("SHA-256 algorithm not available", e);
492	        }
493	    }
494	
495	    /**
496	     * The region whose range contains this owner's postcode, or {@code null} when the postcode is
497	     * absent, not a 4-digit number, or in no known range.
498	     *
499	     * @return the matching region, or {@code null}
500	     */
501	    private String regionFromPostcode() {
502	        if (this.postcode == null) {
503	            return null;
504	        }
505	        int value;
506	        try {
507	            value = Integer.parseInt(this.postcode.trim());
508	        }
509	        catch (NumberFormatException ex) {
510	            return null;
511	        }
512	        for (Map.Entry<String, int[]> entry : REGION_POSTCODE.entrySet()) {
513	            int[] range = entry.getValue();
514	            if (value >= range[0] && value <= range[1]) {
515	                return entry.getKey();
516	            }
517	        }
518	        return null;
519	    }
