525	     * @return {@code 'EMAIL'} when an email address is present, otherwise {@code 'PHONE'}
526	     */
527	    public String getContactPreference() {
528	        boolean hasEmail = this.email != null && !this.email.isBlank();
529	        return hasEmail ? "EMAIL" : "PHONE";
530	    }
