532	    /**
533	     * The owner's identity key, the single derived value used for duplicate detection. It is the
534	     * owner's normalized telephone, email (empty when absent) and household id joined with
535	     * {@code '|'} ({@code '<telephone>|<email>|<householdId>'}); any absent ({@code null}) component
536	     * contributes an empty string. Two owners are duplicates exactly when their whole identity keys
537	     * are equal, so two members of the same household with different telephones differ here and are
538	     * both allowed.
539	     *
540	     * @return the derived identity key
541	     */
542	    public String getIdentityKey() {
543	        return (this.telephone == null ? "" : this.telephone) + "|"
544	            + (this.email == null ? "" : this.email) + "|"
545	            + (this.householdId == null ? "" : this.householdId);
546	    }
