604	    /**
605	     * Stamps the effective registration date exactly once on insert, so every newly persisted owner
606	     * carries a resolved, business-day registration date (see {@link #resolveRegistrationDate}).
607	     */
608	    @PrePersist
609	    void onCreate() {
610	        this.registrationDate = resolveRegistrationDate(this.registrationDate);
611	    }
612	
613	    /**
614	     * Resolves the effective registration date and rolls it onto a business day. An absent
615	     * ({@code null}) value defaults to the server's current date; a supplied value is used as-is.
616	     * The resulting date is then rolled forward so it never falls on a weekend: a Saturday or Sunday
617	     * becomes the following Monday, while any weekday is returned unchanged.
618	     *
619	     * <p>This is the single definition of both the defaulting and the business-day roll, used
620	     * wherever the effective registration date is needed - by the {@code @PrePersist} hook that
621	     * stamps the owner and by the create endpoint that counts owners per business day.
622	     *
623	     * @param supplied the registration date from the request, or {@code null} when none was supplied
624	     * @return the effective registration date, guaranteed to fall on a business day
625	     */
626	    public static LocalDate resolveRegistrationDate(LocalDate supplied) {
627	        LocalDate effective = supplied != null ? supplied : LocalDate.now();
628	        return switch (effective.getDayOfWeek()) {
629	            case SATURDAY -> effective.plusDays(2);
630	            case SUNDAY -> effective.plusDays(1);
631	            default -> effective;
632	        };
633	    }
634	
635	    protected Set<Pet> getPetsInternal() {
636	        if (this.pets == null) {
637	            this.pets = new HashSet<>();
638	        }
639	        return this.pets;
640	    }
641	
642	    protected void setPetsInternal(Set<Pet> pets) {
643	        this.pets = pets;
644	    }
645	
646	    public List<Pet> getPets() {
647	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
648	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
649	        return Collections.unmodifiableList(sortedPets);
650	    }
651	
652	    public void setPets(List<Pet> pets) {
653	        this.pets = new HashSet<>(pets);
654	    }
655	
656	    public void addPet(Pet pet) {
657	        getPetsInternal().add(pet);
658	        pet.setOwner(this);
659	    }
660	
661	    /**
662	     * Return the Pet with the given name, or null if none found for this Owner.
663	     *
664	     * @param name to test
665	     * @return true if pet name is already in use
666	     */
667	    public Pet getPet(String name) {
668	        return getPet(name, false);
669	    }
670	
671	    /**
672	     * Return the Pet with the given name, or null if none found for this Owner.
673	     *
674	     * @param name to test
675	     * @return true if pet name is already in use
676	     */
677	    public Pet getPet(String name, boolean ignoreNew) {
678	        name = name.toLowerCase();
679	        for (Pet pet : getPetsInternal()) {
680	            if (!ignoreNew || !pet.isNew()) {
681	                String compName = pet.getName();
682	                compName = compName.toLowerCase();
683	                if (compName.equals(name)) {
684	                    return pet;
685	                }
686	            }
687	        }
688	        return null;
689	    }
690	
691	    public Pet getPet(Integer petId) {
692	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
693	    }
694	
695	    @Override
696	    public String toString() {
697	        return new ToStringCreator(this)
698	
699	            .append("id", this.getId())
700	            .append("new", this.isNew())
701	            .append("lastName", this.getLastName())
702	            .append("firstName", this.getFirstName())
703	            .append("address", this.address)
704	            .append("city", this.city)
705	            .append("telephone", this.telephone)
706	            .toString();
707	    }
708	}
